        verses = listOf(
            ScriptureVerse(1, "શ્રીગુરુ ચરણ સરોજ રજ, નિજ મનુ મુકુરુ સુધારિ |\nબરનઉં રઘુબર બિમલ જસુ, જો દાયકુ ફલ ચારિ ||", "શ્રી ગુરુ મહારાજના ચરણ કમળની રજથી મારા મનરૂપી દર્પણને પવિત્ર કરી શ્રી રઘુનાથજીના નિર્મળ યશનું વર્ણન કરું છું, જે ધર્મ, અર્થ, કામ અને મોક્ષ ચારેય ફળ આપનાર છે.", "પ્રારંભિક દોહા ૧"),
            ScriptureVerse(2, "બુદ્ધિહીન તનુ જાનિકે, સુમિરૌં પવન-કુમાર |\nબલ બુદ્ધિ વિદ્યા દેહુ મોહિં, હરહુ કલેસ બિકાર ||", "હે પવનકુમાર! હું મારી જાતને બુદ્ધિહીન જાણી તમારું સ્મરણ કરું છું; મને શારીરિક બળ, સદ્બુદ્ધિ અને દિવ્ય વિદ્યા આપો અને મારા સર્વ દુઃખો તથા મનના વિકારોને હરી લો.", "પ્રારંભિક દોહા ૨"),

            ScriptureVerse(3, "જય હનુમાન જ્ઞાન ગુન સાગર |\nજય કપીસ તિહું લોક ઉજાગર ||", "હે હનુમાનજી! આપની જય હો, આપ જ્ઞાન અને ગુણોના અગાધ સાગર છો. હે વાનરરાજ કપીશ્વર! આપની કીર્તિ સ્વર્ગ, પૃથ્વી અને પાતાળ ત્રણેય લોકમાં પ્રકાશિત છે.", "ચોપાઈ ૧"),
            ScriptureVerse(4, "રામ દૂત અતુલિત બલ ધામા |\nઅંજાનિ-પુત્ર પવનસુત નામા ||", "આપ ભગવાન શ્રીરામના પરમ દૂત અને અતુલનીય બળના ધામ છો. આપ માતા અંજનીના પુત્ર અને પવનપુત્ર તરીકે ઓળખાવ છો.", "ચોપાઈ ૨"),
            ScriptureVerse(5, "મહાબીર બિક્રમ બજરંગી |\nકુમતિ નિવાર સુમતિ કે સંગી ||", "હે મહાવીર! આપ વજ્ર સમાન કઠોર અંગોવાળા પરાક્રમી બજરંગબલી છો. આપ કુબુદ્ધિનો નાશ કરો છો અને સદ્બુદ્ધિના સાથી છો.", "ચોપાઈ ૩"),
            ScriptureVerse(6, "કંચન બરન બિરાજ સુબેસા |\nકાનન કુંડલ કુંચિત કેસા ||", "આપનો સુવર્ણ સમાન તેજોમય વર્ણ અને સુંદર વેશભૂષા શોભે છે. આપના કાનમાં રત્નજડિત કુંડળ અને મસ્તક પર ઘૂંઘરાળા કેશ શોભાયમાન છે.", "ચોપાઈ ૪"),
            ScriptureVerse(7, "હાથ બજ્ર ઔ ધ્વજા બિરાજૈ |\nકાંધે મૂંજ જનેઊ સાજૈ ||", "આપના એક હાથમાં વજ્ર અને બીજા હાથમાં ધર્મધ્વજા બિરાજે છે, અને ખભા પર પવિત્ર મુંજનું જનોઈ શોભી રહ્યું છે.", "ચોપાઈ ૫"),
            ScriptureVerse(8, "સંકર સુવન કેસરી નંદન |\nતેજ પ્રતાપ મહા જગ બંદન ||", "આપ ભગવાન શંકરના અંશાવતાર અને રાજા કેસરીના નંદન છો. આપનું તેજ અને પરાક્રમ સમગ્ર જગતમાં વંદનીય છે.", "ચોપાઈ ૬"),
            ScriptureVerse(9, "વિદ્યાવાન ગુની અતિ ચાતુર |\nરામ કાજ કરિબે કો આતુર ||", "આપ ચૌદ વિદ્યાઓના જ્ઞાતા, પરમ ગુણવાન અને અત્યંત ચતુર છો. ભગવાન શ્રીરામના કાર્યો સંપન્ન કરવા આપ સદાય આતુર રહો છો.", "ચોપાઈ ૭"),
            ScriptureVerse(10, "પ્રભુ ચરિત્ર સુનિબે કો રસિયા |\nરામ લખન સીતા મન બસિયા ||", "આપ પ્રભુ શ્રીરામની કથા-ચરિત્ર સાંભળવાના પરમ રસિયા છો. આપના હૃદયમાં શ્રીરામ, લક્ષ્મણજી અને માતા સીતા સદાય વાસ કરે છે.", "ચોપાઈ ૮"),
            ScriptureVerse(11, "સૂક્ષ્મ રૂપ ધરી સિયહિં દિખાવા |\nબિકટ રૂપ ધરી લંક જરાવા ||", "આપે લંકામાં અશોક વાટિકામાં અતિ સૂક્ષ્મ રૂપ ધારણ કરી સીતાજીને દર્શન આપ્યા અને વિશાળ વિકરાળ રૂપ ધરી લંકા નગરીને બાળી નાખી.", "ચોપાઈ ૯"),
            ScriptureVerse(12, "ભીમ રૂપ ધરી અસુર સંહારે |\nરામચંદ્ર કે કાજ સંવારે ||", "આપે મહાકાય ભીમ રૂપ ધારણ કરીને રાક્ષસોનો સંહાર કર્યો અને ભગવાન શ્રીરામચંદ્રજીના તમામ મંગલ કાર્યોને સિદ્ધ કર્યા.", "ચોપાઈ ૧૦"),
            ScriptureVerse(13, "લાય સંજીવન લખન જિયાયે |\nશ્રી રઘુબીર હરષિ ઉર લાયે ||", "આપે દ્રોણાગિરિ પર્વત લાવી સંજીવની બુટીથી લક્ષ્મણજીના પ્રાણ બચાવ્યા, જેથી હર્ષિત થઈ શ્રી રામચંદ્રજીએ આપને હૃદય સરસા ચાંપ્યા.", "ચોપાઈ ૧૧"),
            ScriptureVerse(14, "રઘુપતિ કીન્હી બહુત બડ઼ાઈ |\nતુમ મમ પ્રિય ભરતહિ સમ ભાઈ ||", "શ્રી રાઘવેન્દ્ર પ્રભુએ આપની અપાર પ્રશંસા કરતાં કહ્યું કે તું મને મારા વહાલા ભાઈ ભરત સમાન પ્રિય છો.", "ચોપાઈ ૧૨"),
            ScriptureVerse(15, "સહસ બદન તુમ્હરો જસ ગાવૈં |\nઅસ કહિ શ્રીપતિ કંઠ લગાવૈં ||", "'હજાર મુખવાળા શેષનાગ આપના યશનું ગાન કરે છે' - એમ કહીને લક્ષ્મીપતિ પ્રભુ શ્રીરામે આપને સ્નેહપૂર્વક કંઠે લગાવ્યા.", "ચોપાઈ ૧૩"),
            ScriptureVerse(16, "સનકાદિક બ્રહ્માદિ મુનીસા |\nનારદ સારદ સહિત અહીસા ||", "સનક, સનંદન આદિ ઋષિમુનિઓ, બ્રહ્માજી, દેવર્ષિ નારદ, માતા સરસ્વતી અને શેષનાગ સહિત સર્વે આપની સ્તુતિ કરે છે.", "ચોપાઈ ૧૪"),
            ScriptureVerse(17, "જમ કુબેર દિગપાલ જહાં તે |\nકબિ કોબિદ કહિ સકે કહાં તે ||", "યમરાજ, ધનાધિપતિ કુબેર અને દશે દિશાઓના પાલકો આપના યશનું વર્ણન કરી શકતા નથી, તો પછી સામાન્ય કવિઓ કે વિદ્વાનો કઈ રીતે કરી શકે?", "ચોપાઈ ૧૫"),
            ScriptureVerse(18, "તુમ ઉપકાર સુગ્રીવહિં કીન્હા |\nરામ મિલાય રાજ પદ દીન્હા ||", "આપે સુગ્રીવજી પર મોટો ઉપકાર કર્યો, તેમને શ્રીરામ સાથે મિલાવીને કિષ્કિંધાનું રાજપદ અપાવ્યું.", "ચોપાઈ ૧૬"),
            ScriptureVerse(19, "તુમ્હરો મંત્ર બિભીષન માના |\nલંકેશ્વર ભયે સબ જગ જાના ||", "આપના હિતકારી ઉપદેશને વિભીષણે સ્વીકાર્યો, જેના ફળસ્વરૂપે તેઓ લંકાના રાજા બન્યા - આ વાત આખું જગત જાણે છે.", "ચોપાઈ ૧૭"),
            ScriptureVerse(20, "જુગ સહસ્ર જોજન પર ભાનૂ |\nલીલ્યો તાહિ મધુર ફલ જાનૂ ||", "જે સૂર્ય પૃથ્વીથી હજારો યોજન દૂર સ્થિત છે, તેને આપે બાળપણમાં મધુર ફળ સમજીને એક જ છલાંગમાં ગળી લીધો હતો.", "ચોપાઈ ૧૮"),
            ScriptureVerse(21, "પ્રભુ મુદ્રિકા મેલિ મુખ માહી |\nજલધિ લાંઘિ ગયે અચરજ નાહી ||", "આપે પ્રભુ શ્રીરામની વીંટી મુખમાં રાખી અગાધ સમુદ્ર પાર કરી લીધો, આપના જેવા સમર્થ માટે એમાં કોઈ આશ્ચર્ય નથી.", "ચોપાઈ ૧૯"),
            ScriptureVerse(22, "દુર્ગમ કાજ જગત કે જેતે |\nસુગમ અનુગ્રહ તુમ્હરે તેતે ||", "આ સંસારમાં જેટલા પણ કઠિન અને અસંભવ કાર્યો છે, તે બધા આપની કૃપા માત્રથી સહજ અને સુગમ બની જાય છે.", "ચોપાઈ ૨૦"),
            ScriptureVerse(23, "રામ દુઆરે તુમ રખવારે |\nહોત ન આજ્ઞા બિનુ પૈસારે ||", "આપ શ્રીરામના દરબારના રક્ષક છો. આપની પરવાનગી વિના કોઈ પણ ત્યાં પ્રવેશી શકતું નથી.", "ચોપાઈ ૨૧"),
            ScriptureVerse(24, "સબ સુખ લહૈ તુમ્હારી સરના |\nતુમ રક્ષક કાહૂ કો ડર ના ||", "જે આપની શરણમાં આવે છે તેને સર્વ સુખોની પ્રાપ્તિ થાય છે. આપ જેમના રક્ષક હો તેને કોઈ વાતનો ડર રહેતો નથી.", "ચોપાઈ ૨૨"),
            ScriptureVerse(25, "આપન તેજ સંહારો આપૈ |\nતીનોં લોક હાંક તેં કાંપૈ ||", "આપના અસીમ તેજને આપ પોતે જ સંભાળી શકો છો. આપના એક માત્ર હૂંકારથી ત્રણેય લોક થરથર કાંપવા લાગે છે.", "ચોપાઈ ૨૩"),
            ScriptureVerse(26, "ભૂત પિસાચ નિકટ નહિં આવૈ |\nમહાબીર જબ નામ સુનાવૈ ||", "જ્યાં મહાવીર હનુમાનજીનું પાવન નામ લેવાય છે, ત્યાં ભૂત, પિશાચ કે કોઈ પણ નકારાત્મક શક્તિઓ નજીક પણ આવી શકતી નથી.", "ચોપાઈ ૨૪"),
            ScriptureVerse(27, "નાસૈ રોગ હરૈ સબ પીરા |\nજપત નિરંતર હનુમત બીરા ||", "જે ભક્ત નિરંતર વીર હનુમાનજીના નામનો જપ કરે છે, તેના સર્વ રોગોનો નાશ થાય છે અને બધી શારીરિક-માનસિક પીડાઓ હરાય છે.", "ચોપાઈ ૨૫"),
            ScriptureVerse(28, "સંકટ તેં હનુમાન છુડ઼ાવૈ |\nમન ક્રમ બચન ધ્યાન જો લાવૈ ||", "જે મનુષ્ય મન, વચન અને કર્મથી હનુમાનજીનું ધ્યાન ધરે છે, તેને હનુમાનજી સર્વ સંકટોમાંથી મુક્ત કરે છે.", "ચોપાઈ ૨૬"),
            ScriptureVerse(29, "સબ પર રામ તપસ્વી રાજા |\nતિન કે કાજ સકલ તુમ સાજા ||", "તપસ્વી રાજા શ્રીરામચંદ્રજી સર્વોપરી છે, અને આપે તેમના તમામ મુશ્કેલ કાર્યોને સફળતાપૂર્વક સિદ્ધ કર્યા.", "ચોપાઈ ૨૭"),
            ScriptureVerse(30, "ઔર મનોરથ જો કોઈ લાવૈ |\nસોઈ અમિત જીવન ફલ પાવૈ ||", "આપની સમક્ષ ભક્ત જે કોઈ મનોકામના લઈને આવે છે, તેને એવું અમૂલ્ય ફળ પ્રાપ્ત થાય છે જે જીવનભર અક્ષય રહે છે.", "ચોપાઈ ૨૮"),
            ScriptureVerse(31, "ચારોં જુગ પરતાપ તુમ્હારા |\nહૈ પરસિદ્ધ જગત ઉજિયારા ||", "સત્યયુગ, ત્રેતા, દ્વાપર અને કળિયુગ - ચારેય યુગોમાં આપનો પ્રતાપ વિદ્યમાન છે. આપની કીર્તિથી સમગ્ર વિશ્વ પ્રકાશિત છે.", "ચોપાઈ ૨૯"),
            ScriptureVerse(32, "સાધુ સંત કે તુમ રખવારે |\nઅસુર નિકંદન રામ દુલારે ||", "આપ સાધુ-સંતો અને સજ્જનોના રક્ષક છો, અસુરોનો સંહાર કરનારા છો અને ભગવાન શ્રીરામના અત્યંત વહાલા છો.", "ચોપાઈ ૩૦"),
            ScriptureVerse(33, "અષ્ટ સિદ્ધિ નૌ નિધિ કે દાતા |\nઅસ બર દીન જાનકી માતા ||", "માતા જાનકીએ આપને એવું વરદાન આપ્યું છે કે આપ આપના ભક્તોને આઠેય સિદ્ધિઓ અને નવેય નિધિઓ આપવા સમર્થ છો.", "ચોપાઈ ૩૧"),
            ScriptureVerse(34, "રામ રસાયન તુમ્હરે પાસા |\nસદા રહો રઘુપતિ કે દાસા ||", "આપની પાસે રામનામ રૂપી અમૃત રસાયણ છે. આપ સદાય ભગવાન શ્રી રઘુનાથજીના પરમ દાસ બનીને રહો છો.", "ચોપાઈ ૩૨"),
            ScriptureVerse(35, "તુમ્હરે ભજન રામ કો ભાવૈ |\nજનમ જનમ કે દુખ બિસરાવૈ ||", "આપના ભજન-કીર્તનથી ભગવાન શ્રીરામ પ્રસન્ન થાય છે અને જીવના જન્મોજન્મના દુઃખ અને સંતાપ દૂર થઈ જાય છે.", "ચોપાઈ ૩૩"),
            ScriptureVerse(36, "અંત કાલ રઘુબર પુર જાઈ |\nજહાં જન્મ હરિ-ભક્ત કહાઈ ||", "આપનું સ્મરણ કરનાર અંતકાળે શ્રીરામના પરમધામ સાકેતમાં જાય છે અને પુનઃ જન્મ થાય તો હરિભક્ત તરીકે પૂજાય છે.", "ચોપાઈ ૩૪"),
            ScriptureVerse(37, "ઔર દેવતા ચિત્ત ન ધરઈ |\nહનુમત સેઈ સર્બ સુખ કરઈ ||", "અન્ય કોઈ દેવતાનું ચિંતન કર્યા વિના પણ જો કેવળ હનુમાનજીની સેવા કરવામાં આવે, તો પણ સર્વ સુખોની પ્રાપ્તિ થાય છે.", "ચોપાઈ ૩૫"),
            ScriptureVerse(38, "સંકટ કટૈ મિટૈ સબ પીરા |\nજો સુમિરૈ હનુમત બલબીરા ||", "જે મનુષ્ય બળવાન વીર હનુમાનજીનું સ્મરણ કરે છે, તેના જીવનના તમામ સંકટો કપાઈ જાય છે અને સર્વ કષ્ટો મટી જાય છે.", "ચોપાઈ ૩૬"),
            ScriptureVerse(39, "જય જય જય હનુમાન ગોસાઈ |\nકૃપા કરહુ ગુરુ દેવ કી નાઈ ||", "હે પ્રભુ હનુમાનજી! આપની જય હો, જય હો, જય હો! આપ સદ્ગુરુની જેમ મારા પર સદાય કૃપાદૃષ્ટિ વરસાવો.", "ચોપાઈ ૩૭"),
            ScriptureVerse(40, "જો સત બાર પાઠ કર કોઈ |\nછૂટહિ બંદિ મહા સુખ હોઈ ||", "જે ભક્ત આ ચાલીસાનો સો વખત પાઠ કરે છે, તે સંસારના સર્વ બંધનોમાંથી મુક્ત થઈને પરમ આનંદ પ્રાપ્ત કરે છે.", "ચોપાઈ ૩૮"),
            ScriptureVerse(41, "જો યહ પઢ઼ૈ હનુમાન ચાલીસા |\nહોય સિદ્ધિ સાખી ગૌરીસા ||", "જે મનુષ્ય આ હનુમાન ચાલીસાનું નિત્ય પઠન કરે છે તેને સર્વ કાર્યોમાં સિદ્ધિ મળે છે - આ વાતના સાક્ષી સ્વયં ભગવાન શિવ છે.", "ચોપાઈ ૩૯"),
            ScriptureVerse(42, "તુલસીદાસ સદા હરિ ચેરા |\nકીજૈ નાથ હૃદય મહઁ ડેરા ||", "તુલસીદાસ સદાય શ્રીહરિના દાસ છે; હે નાથ! આપ મારા હૃદયમાં કાયમ માટે નિવાસ કરો.", "ચોપાઈ ૪૦"),

            ScriptureVerse(43, "પવનતનય સંકટ હરન, મંગલ મૂરતિ રૂપ |\nરામ લખન સીતા સહિત, હૃદય બસહુ સુર ભૂપ ||", "હે પવનપુત્ર! સંકટોને હરનારા, મંગલકારી દિવ્ય રૂપવાળા હે દેવાધિરાજ! આપ શ્રીરામ, લક્ષ્મણ અને માતા સીતા સહિત સદાય મારા હૃદયકમળમાં બિરાજો.", "સમાપન દોહા")
        )
    )

    val shivChalisa = DevotionalScripture(
        id = "shiv_chalisa",
        titleGujarati = "શ્રી શિવ ચાલીસા",
        deityName = "ભગવાન શિવ",
        category = ContentCategory.CHALISA,
        introductionGujarati = "દેવાધિદેવ ભોળાનાથ મહાદેવની પરમ મંગલકારી ચાલીસા, સંપૂર્ણ ૪૦ ચોપાઈ અને દોહા અર્થ સહિત.",
        verses = listOf(
            ScriptureVerse(1, "જય ગણેશ ગિરિજા સુવન, મંગલ મૂલ સુજાન |\nકહત અયોધ્યાદાસ તુમ, દેહુ અભય વરદાન ||", "શ્રી ગણેશજી અને માતા પાર્વતીના પુત્રની જય હો, જે સમસ્ત મંગલના મૂળ અને જ્ઞાની છે. અયોધ્યાદાસ કહે છે કે હે પ્રભુ, આપ સર્વને અભય વરદાન આપો.", "દોહા"),

            ScriptureVerse(2, "જય ગિરિજા પતિ દીનદયાળા |\nસદા કરત સંતન પ્રતિપાલા ||", "હે પાર્વતીપતિ! હે દીનદયાળુ શંભુ! આપની જય હો. આપ સદાય સંતો, સાધુઓ અને ભક્તોનું પાલનપોષણ કરો છો.", "ચોપાઈ ૧"),
            ScriptureVerse(3, "ભાલ ચંદ્રમા સોહત નીકે |\nકાનન કુંડલ નાગફણી કે ||", "આપના મસ્તક પર દ્વિતીયાનો સુંદર ચંદ્ર શોભે છે અને કાનમાં નાગફેણીના મનોહર કુંડળ શોભાયમાન છે.", "ચોપાઈ ૨"),
            ScriptureVerse(4, "અંગ ગૌર શિર ગંગ બહાયે |\nમુંડમાલ તન છાર લગાયે ||", "આપનો ગોરો દિવ્ય વર્ણ છે, મસ્તક પર પવિત્ર ગંગાજી વહે છે. ગળામાં મુંડમાળા અને સમગ્ર અંગ પર ભસ્મ શોભે છે.", "ચોપાઈ ૩"),
            ScriptureVerse(5, "વસ્ત્ર ખાલ બાઘમ્બર સોહૈં |\nછબિ કો દેખિ નાગ મુનિ મોહૈં ||", "આપે વાઘાંબર (વાઘનું ચર્મ) ધારણ કર્યું છે. આપના આ અલૌકિક સ્વરૂપને જોઈ નાગ અને ઋષિમુનિઓ મોહિત થાય છે.", "ચોપાઈ ૪"),
            ScriptureVerse(6, "મૈના માતુ કી હવૈ દુલારી |\nબામ અંગ સોહત છબિ ન્યારી ||", "માતા મૈનાની વહાલી પુત્રી ભગવતી પાર્વતી આપના ડાબા અંગે બિરાજે છે, જે દર્શન અત્યંત દિવ્ય લાગે છે.", "ચોપાઈ ૫"),
            ScriptureVerse(7, "કર ત્રિશૂલ સોહત શુચિ ભાલા |\nદાદિ સકલ શત્રુન કે કાલા ||", "આપના હાથમાં પવિત્ર ત્રિશૂલ શોભે છે, જે દુષ્ટ શત્રુઓ અને દાનવો માટે કાળ સમાન છે.", "ચોપાઈ ૬"),
            ScriptureVerse(8, "નંદી ભૃંગી ગણ સોહૈં સંગા |\nનાચત તાલ મૃદંગા ચંગા ||", "આપની સાથે નંદી અને ભૃંગી સહિત શિવગણો શોભે છે. ડમરુ અને મૃદંગના તાલ પર દિવ્ય તાંડવ નૃત્ય થાય છે.", "ચોપાઈ ૭"),
            ScriptureVerse(9, "શીતલ મંદ સુગંધ સુહાઈ |\nપવન ચલત સબ તાપ મિટાઈ ||", "કૈલાસ પર શીતળ, મંદ અને સુગંધિત પવન વાય છે જે સમસ્ત ભક્તોના સંતાપ અને તાપ મિટાવી દે છે.", "ચોપાઈ ૮"),
            ScriptureVerse(10, "દેવન જબહીં જાય પુકારા |\nતબહીં દુઃખ પ્રભુ આપ નિવારા ||", "જ્યારે જ્યારે દેવતાઓ પર સંકટ આવ્યું અને તેમણે પોકાર કર્યો, ત્યારે પ્રભુ આપે સ્વયં તેમના દુઃખોનું નિવારણ કર્યું.", "ચોપાઈ ૯"),
            ScriptureVerse(11, "કિયા ઉપદ્રવ તારક ભારી |\nદેવન સબ મિલિ તુમહિં જુહારી ||", "જ્યારે તારકાસુર દાનવે ભારે ઉપદ્રવ મચાવ્યો, ત્યારે બધા દેવતાઓએ આપના શરણે આવીને પ્રાર્થના કરી.", "ચોપાઈ ૧૦"),
            ScriptureVerse(12, "તુરત ષડાનન આપ પઠાયો |\nલવિ નિમેષ મહઁ મારિ ગિરાયો ||", "આપે તુરંત કાર્તિકેય (ષડાનન) પ્રભુને મોકલ્યા, જેમણે પલકવારમાં તારકાસુરનો વધ કરીને દેવોને અભય કર્યા.", "ચોપાઈ ૧૧"),
            ScriptureVerse(13, "આપ જલંધર અસુર સંહારા |\nસુયશ તુમ્હાર વિદિત સંસારા ||", "આપે અત્યાચારી જલંધર અસુરનો સંહાર કર્યો; આપનો યશ સમગ્ર વિશ્વમાં સુવિખ્યાત છે.", "ચોપાઈ ૧૨"),
            ScriptureVerse(14, "ત્રિપુરાસુર સન યુદ્ધ મચાયા |\nસબહિં કૃપા કરિ લીન બચાયા ||", "ત્રિપુરાસુર રાક્ષસ સાથે યુદ્ધ કરીને તેનો નાશ કર્યો અને ત્રણેય લોક પર કૃપા કરી સર્વનું રક્ષણ કર્યું.", "ચોપાઈ ૧૩"),
            ScriptureVerse(15, "ભાગીરથિ તપ કિયો અનોખા |\nતબ પ્રભુ ગંગા શીશ સમોખા ||", "જ્યારે રાજા ભગીરથે કઠોર તપસ્યા કરી, ત્યારે આપે સ્વર્ગમાંથી ઉતરતી ગંગાજીના પ્રચંડ વેગને આપની જટામાં સમાવી લીધો.", "ચોપાઈ ૧૪"),
            ScriptureVerse(16, "દાનિન મહઁ તુમ સમ કોઉ નાહીં |\nસેવક અસ્તુતિ કરત સદાહીં ||", "આપના જેવો મોટો દાતા (ઔઢરદાની) ત્રિલોકમાં કોઈ નથી; આપના સેવકો સદાય આપની સ્તુતિ કરે છે.", "ચોપાઈ ૧૫"),
            ScriptureVerse(17, "વેદ માહિં મહિમા તુમ ગાઈ |\nઅકથ અનાદિ ભેદ નહિં પાઈ ||", "વેદો અને ઉપનિષદોમાં આપની મહિમા ગવાઈ છે. આપ અકથ્ય, અનાદિ અને અનંત છો, આપનો પાર કોઈ પામી શકતું નથી.", "ચોપાઈ ૧૬"),
            ScriptureVerse(18, "પ્રગટ ઉદધિ મંથન મેં જ્વાલા |\nજરત સુરાસુર ભયે બિહાલા ||", "સમુદ્ર મંથન વખતે જ્યારે ભયંકર હળાહળ વિષની જ્વાળાઓ પ્રગટ થઈ અને દેવ-દાનવો વ્યાકુળ બન્યા;", "ચોપાઈ ૧૭"),
            ScriptureVerse(19, "કીન્હ દયા તહઁ કરી સહાયી |\nનીલકંઠ તબ નામ કહાયી ||", "ત્યારે આપે દયા કરી એ વિષને કંઠમાં ધારણ કરી લીધું, જેથી આપનું નામ જગતમાં 'નીલકંઠ' કહેવાયું.", "ચોપાઈ ૧૮"),
            ScriptureVerse(20, "પૂજન કીન્હ રામચંદ્ર જબ |\nજીત કે લંક વિભીષણ દીન્હ તબ ||", "લંકા વિજય પૂર્વે જ્યારે ભગવાન શ્રી રામચંદ્રજીએ રામેશ્વરમમાં આપનું પૂજન કર્યું, ત્યારે લંકા પર વિજય પ્રાપ્ત થયો.", "ચોપાઈ ૧૯"),
            ScriptureVerse(21, "સહસ કમલ મેં હો રહે ધારી |\nકીન્હ પરીક્ષા તબહિં ત્રિપુરારી ||", "શ્રીરામના સહસ્ર કમલ પૂજન સમયે આપે એક કમલ છુપાવી પરીક્ષા લીધી, ત્યારે શ્રીરામે પોતાનું નેત્રકમળ અર્પણ કરવા તૈયારી દર્શાવી.", "ચોપાઈ ૨૦"),
            ScriptureVerse(22, "એક કમલ પ્રભુ રાખેઉ ગોઈ |\nકમલ નયન પૂજન ચહં સોઈ ||", "શ્રીરામ પોતાના કમલ સમાન નેત્રનું બલિદાન આપવા તત્પર થયા ત્યારે આપે પ્રગટ થઈ મનોવાંછિત વિજય વરદાન આપ્યું.", "ચોપાઈ ૨૧"),
            ScriptureVerse(23, "કઠિન ભક્તિ દેખી પ્રભુ ખુશ ભયે |\nઇચ્છિત વર અર્પણ કરી દયે ||", "શ્રીરામની અનન્ય કઠિન ભક્તિ જોઈ આપ પ્રસન્ન થયા અને અજેય વિજયનું વરદાન આપ્યું.", "ચોપાઈ ૨૨"),
            ScriptureVerse(24, "જય જય જય અક્ષય અવિનાશી |\nકૃપા કરો સબ કે ઘટ વાસી ||", "હે અવિનાશી, અક્ષય પરમાત્મા! આપની સદા જય હો. સર્વ પ્રાણીઓના હૃદયમાં વાસ કરનારા પ્રભુ, અમારા પર કૃપા કરો.", "ચોપાઈ ૨૩"),
            ScriptureVerse(25, "દુષ્ટ સકલ મોહિં આન સતાવૈં |\nભ્રમિત રહૌં મોહિં ચૈન ન આવૈ ||", "જ્યારે દુષ્ટ વિચારો કે વિપત્તિઓ મને સતાવે છે અને મન ભ્રમિત થઈ અશાંત બને છે,", "ચોપાઈ ૨૪"),
            ScriptureVerse(26, "ત્રાહિ ત્રાહિ મૈં નાથ પુકારો |\nયહિ અવસર મોહિ આન ઉબારો ||", "ત્યારે હે નાથ! હું આપને રક્ષા માટે પોકારું છું. આ સંકટ સમયે આવીને મારો ઉદ્ધાર કરો.", "ચોપાઈ ૨૫"),
            ScriptureVerse(27, "લે ત્રિશૂલ શત્રુન કો મારો |\nસંકટ સે મોહિ આન ઉબારો ||", "આપનું ત્રિશૂલ ઉઠાવી આંતરિક કામ, ક્રોધ આદિ શત્રુઓનો નાશ કરો અને મને સંકટોમાંથી ઉગારી લો.", "ચોપાઈ ૨૬"),
            ScriptureVerse(28, "માત પિતા ભ્રાતા સબ હોઈ |\nસંકટ મેં પૂછત નહિં કોઈ ||", "સંસારમાં માતા, પિતા, ભાઈ સર્વે સંબંધીઓ છે, પરંતુ અંતિમ સંકટમાં આપના સિવાય કોઈ સાચો સહારો નથી.", "ચોપાઈ ૨૭"),
            ScriptureVerse(29, "સ્વામી એક હૈ આસ તુમ્હારી |\nઆય હરહુ મમ સંકટ ભારી ||", "હે ત્રિલોકના સ્વામી! મને કેવળ આપની જ આશા છે; આપ આવીને મારા ભારે સંકટોને હરી લો.", "ચોપાઈ ૨૮"),
            ScriptureVerse(30, "ધન નિર્ધન કો દેત સદા હી |\nજો કોઈ જાંચે સો ફલ પાહી ||", "આપ નિર્ધનને ધન અને જ્ઞાન આપો છો. જે કોઈ શ્રદ્ધાપૂર્વક આપની યાચના કરે છે તે મનોવાંછિત ફળ પામે છે.", "ચોપાઈ ૨૯"),
            ScriptureVerse(31, "અસ્તુતિ કેહિ બિધિ કરૌં તુમ્હારી |\nક્ષમહુ નાથ અબ ચૂક હમારી ||", "હું અજ્ઞાની કઈ રીતે આપની યોગ્ય સ્તુતિ કરી શકું? હે નાથ! મારી સર્વ ભૂલો અને અપરાધોને ક્ષમા કરો.", "ચોપાઈ ૩૦"),
            ScriptureVerse(32, "શંકર હો સંકટ કે નાશન |\nમંગલ કારન વિઘ્ન વિનાશન ||", "હે શંકર ભગવાન! આપ સર્વ સંકટોનો નાશ કરનારા, સદાય મંગલ કરનારા અને વિઘ્નો હરનારા છો.", "ચોપાઈ ૩૧"),
            ScriptureVerse(33, "યોગી યતિ મુનિ ધ્યાન લગાવૈં |\nશારદ નારદ શીશ નવાવૈં ||", "યોગીઓ, સંન્યાસીઓ અને મુનિઓ આપનું ધ્યાન ધરે છે. માતા સરસ્વતી અને દેવર્ષિ નારદ આપને મસ્તક નમાવે છે.", "ચોપાઈ ૩૨"),
            ScriptureVerse(34, "નમો નમો જય નમઃ શિવાય |\nસુર બ્રહ્માદિક પાર ન પાય ||", "ૐ નમઃ શિવાય મંત્રને વારંવાર નમસ્કાર છે! દેવતાઓ અને બ્રહ્માજી પણ આપની પૂર્ણ લીલાનો પાર પામી શકતા નથી.", "ચોપાઈ ૩૩"),
            ScriptureVerse(35, "જો યહ પાઠ કરે મન લાઈ |\nતાપર હોત સંભુ સહાયી ||", "જે મનુષ્ય એકાગ્ર ચિત્તે આ ચાલીસાનો પાઠ કરે છે, તેના પર સદા ભગવાન શંભુ સહાયક બને છે.", "ચોપાઈ ૩૪"),
            ScriptureVerse(36, "ઋણિયા જો કોઈ હોય અપારા |\nછૂટત પાઠ કરે શિવ દ્વારા ||", "જે વ્યક્તિ ભારે દેવામાં ડૂબેલો હોય, તે શિવજીના ચરણે આ પાઠ કરે તો સર્વ દેવામાંથી મુક્ત થાય છે.", "ચોપાઈ ૩૫"),
            ScriptureVerse(37, "ધ્યાન ધરે જો મન ચિત લાઈ |\nતાકો દુઃખ કછુ નહિં રહાઈ ||", "જે સાચા મનથી ભોળાનાથનું ધ્યાન ધરે છે, તેના જીવનમાં કોઈ પણ પ્રકારનું દુઃખ રહેતું નથી.", "ચોપાઈ ૩૬"),
            ScriptureVerse(38, "પુત્રહીન જો ઇચ્છા કરઈ |\nશિવ કૃપા તે સો ફલ પાવઈ ||", "જે પુત્રહીન શ્રદ્ધાપૂર્વક સંતાન પ્રાપ્તિની ઇચ્છા કરે છે, તે શિવકૃપાથી સુપુત્ર પ્રાપ્ત કરે છે.", "ચોપાઈ ૩૭"),
            ScriptureVerse(39, "પંચામૃત સે સ્નાન કરાવૈ |\nચંદન અક્ષત પુષ્પ ચઢ઼ાવૈ ||", "જે ભક્ત શિવલિંગને પંચામૃતથી સ્નાન કરાવી ચંદન, અક્ષત, બિલીપત્ર અને પુષ્પ અર્પણ કરે છે,", "ચોપાઈ ૩૮"),
            ScriptureVerse(40, "ધૂપ દીપ નૈવેદ્ય ચઢ઼ાવૈ |\nશંકર સન્મુખ પાઠ સુનાવૈ ||", "ધૂપ, દીપ અને નૈવેદ્ય અર્પણ કરી શિવજીની સન્મુખ આ ચાલીસાનો પાઠ સંભળાવે છે,", "ચોપાઈ ૩૯"),
            ScriptureVerse(41, "સબ મનોકામના પૂર્ણ હોઈ |\nઅંત કાલ શિવપુરી સો સોઈ ||", "તેની સર્વ મનોકામનાઓ પૂર્ણ થાય છે અને અંતકાળે તે પવિત્ર શિવલોક (શિવપુરી) પ્રાપ્ત કરે છે.", "ચોપાઈ ૪૦"),

            ScriptureVerse(42, "નિત્ય નેમ કર પ્રાતઃ હી, પાઠ કરો ચાલીસા |\nતુમ મેરી મનોકામના, પૂર્ણ કરો જગદીશા ||", "નિત્ય નિયમપૂર્વક પ્રભાતમાં જે આ શિવ ચાલીસાનો પાઠ કરે છે, હે જગદીશ્વર શિવ! આપ તેની સર્વ મનોકામનાઓ પૂર્ણ કરો.", "સમાપન દોહા")
        )
    )

    val ganeshAtharvashirsha = DevotionalScripture(
        id = "ganesh_atharvashirsha",
        titleGujarati = "શ્રી ગણેશ અથર્વશીર્ષ",
        deityName = "શ્રી ગણેશ",
        category = ContentCategory.STOTRA,
        introductionGujarati = "વેદોક્ત અથર્વવેદમાંથી પ્રગટ થયેલું ગણેશજીનું પરમ દિવ્ય સ્તોત્ર, સંપૂર્ણ ૧૩ વૈદિક મંત્રો અર્થ સહિત.",
        verses = listOf(
            ScriptureVerse(1, "ૐ ભદ્રં કર્ણેભિઃ શ્રૃણુયામ દેવાઃ |\nભદ્રં પશ્યેમાક્ષભિર્યજત્રાઃ |\nસ્થિરૈરંગૈસ્તુષ્ટુવાંસસ્તનૂભિઃ |\nવ્યશેમ દેવહિતં યદાયુઃ ||\nૐ શાંતિઃ શાંતિઃ શાંતિઃ ||", "હે દેવો! અમે કાનથી શુભ સાંભળીએ, આંખોથી કલ્યાણકારી દર્શન કરીએ. સુદ્રઢ અંગોવાળા શરીરથી આપની સ્તુતિ કરતા રહીને દેવોએ આપેલું આયુષ્ય ધર્મકાર્યમાં વિતાવીએ. ત્રિવિધ તાપની શાંતિ થાઓ.", "શાંતિ મંત્ર"),
            ScriptureVerse(2, "ૐ નમસ્તે ગણપતયે |\nત્વમેવ પ્રત્યક્ષં તત્ત્વમસિ |\nત્વમેવ કેવલં કર્તાઽસિ |\nત્વમેવ કેવલં ધર્તાઽસિ ||", "હે ગણપતિ! આપને સાષ્ટાંગ નમસ્કાર છે. આપ જ પ્રત્યક્ષ પરમતત્ત્વ છો. આપ જ આ સમગ્ર સૃષ્ટિના એકમાત્ર સૃર્જનહાર (કર્તા) છો અને આપ જ તેનું ધારણ-પોષણ કરનારા (ધર્તા) છો.", "મંત્ર ૧ (પરમતત્ત્વ સ્તુતિ)"),
            ScriptureVerse(3, "ત્વમેવ કેવલં હર્તાઽસિ |\nત્વમેવ સર્વં ખલ્વિદં બ્રહ્માસિ |\nત્વં સાક્ષાદાત્માઽસિ નિત્યમ્ ||", "આપ જ આ સૃષ્ટિના અંતે સંહારક (હર્તા) છો. આ સર્વ જગતમાં આપ બ્રહ્મરૂપે વ્યાપી રહ્યા છો. આપ સાક્ષાત્ નિત્ય આત્મતત્ત્વ છો.", "મંત્ર ૨ (સર્વવ્યાપકતા)"),
            ScriptureVerse(4, "ઋતં વચ્મિ |\nસત્યં વચ્મિ |", "હું યથાર્થ (માનસિક સત્ય) બોલું છું. હું પરમ સત્ય (વાસ્તવિક દિવ્ય સત્ય) કહું છું.", "મંત્ર ૩ (સત્ય વચન)"),
            ScriptureVerse(5, "અવ ત્વં મામ્ |\nઅવ વક્તારમ્ |\nઅવ શ્રોતારમ્ |\nઅવ દાતારમ્ |\nઅવ ધાતારમ્ |\nઅવાનૂચાનમવ શિષ્યમ્ ||", "હે ગણેશ! આપ મારું રક્ષણ કરો. આ સ્તોત્ર બોલનાર (વક્તા)નું રક્ષણ કરો, સાંભળનાર (શ્રોતા)નું રક્ષણ કરો, દાન આપનાર દાતા અને ધારણ કરનાર ધાતાનું રક્ષણ કરો, ગુરુ અને શિષ્યનું સર્વ પ્રકારે રક્ષણ કરો.", "મંત્ર ૪ (રક્ષણ યાચના)"),
            ScriptureVerse(6, "અવ પશ્ચાત્તાત્ | અવ પુરસ્તાત્ |\nઅવ ઉત્તરાત્તાત્ | અવ દક્ષિણાત્તાત્ |\nઅવ ચોર્ધ્વાત્તાત્ | અવાધરાત્તાત્ |\nસર્વતો માં પાહિ પાહિ સમન્તાત્ ||", "પાછળથી, આગળથી, ઉત્તરમાંથી, દક્ષિણમાંથી, ઊર્ધ્વ (ઉપર) અને અધર (નીચે)થી - ચારેય દિશાઓ અને વિદિશાઓમાંથી આપ મારી સદાય રક્ષા કરો.", "મંત્ર ૫ (દિશા રક્ષણ)"),
            ScriptureVerse(7, "ત્વં વાઙ્મયસ્ત્વં ચિન્મયઃ |\nત્વમાનન્દમયસ્ત્વં બ્રહ્મમયઃ |\nત્વં સચ્ચિદાનન્દાઽદ્વિતીયોઽસિ |\nત્વં પ્રત્યક્ષં બ્રહ્માસિ |\nત્વં જ્ઞાનમયો વિજ્ઞાનમયોઽસિ ||", "આપ શબ્દરૂપ (વાઙ્મય) છો, ચૈતન્યરૂપ (ચિન્મય) છો. આપ આનંદરૂપ અને બ્રહ્મસ્વરૂપ છો. આપ સત્-ચિત્-આનંદ અદ્વિતીય પરમાત્મા છો. આપ સાક્ષાત્ પ્રત્યક્ષ બ્રહ્મ છો, જ્ઞાન અને વિજ્ઞાનના સાગર છો.", "મંત્ર ૬ (દિવ્ય સ્વરૂપ)"),
            ScriptureVerse(8, "સર્વં જગદિદં ત્વત્તો જાયતે |\nસર્વં જગદિદં ત્વત્તસ્તિષ્ઠતિ |\nસર્વં જગદિદં ત્વયિ લયમેષ્યતિ |\nસર્વં જગદિદં ત્વયિ પ્રત્યેતિ |\nત્વં ભૂમિરાપોઽનલોઽનિલો નભઃ |\nત્વં ચત્વારિ વાક્પદાનિ ||", "આ સમગ્ર વિશ્વ આપનામાંથી ઉત્પન્ન થાય છે, આપનામાં સ્થિર રહે છે અને આપનામાં જ લય પામે છે. આપ પૃથ્વી, જળ, અગ્નિ, વાયુ અને આકાશ એ પંચમહાભૂત છો, અને પરા, પશ્યન્તી, મધ્યમા અને વૈખરી એ ચાર વાણી છો.", "મંત્ર ૭ (સૃષ્ટિ અને વાણી)"),
            ScriptureVerse(9, "ત્વં ગુણત્રયાતીતઃ | ત્વં અવસ્થાત્રયાતીતઃ |\nત્વં દેહત્રયાતીતઃ | ત્વં કાલત્રયાતીતઃ |\nત્વં મૂલાધારસ્થિતોઽસિ નિત્યમ્ |\nત્વં શક્તિત્રયાત્મકઃ |\nત્વાં યોગિનો ધ્યાયન્તિ નિત્યમ્ ||", "આપ સત્ત્વ, રજ અને તમ ત્રણેય ગુણોથી પર છો. જાગ્રત, સ્વપ્ન અને સુષુપ્તિ ત્રણેય અવસ્થાઓથી પર છો. સ્થૂળ, સૂક્ષ્મ અને કારણ દેહથી પર છો. ભૂત, ભવિષ્ય અને વર્તમાન ત્રણેય કાળથી પર છો. આપ મૂલાધાર ચક્રમાં નિત્ય વિરાજો છો. ઇચ્છા, જ્ઞાન અને ક્રિયા શક્તિરૂપ છો. યોગીઓ આપનું નિત્ય ધ્યાન ધરે છે.", "મંત્ર ૮ (ત્રિગુણાતીત ગણેશ)"),
            ScriptureVerse(10, "ગણાકિંગ પૂર્વમુચ્ચાર્ય વર્ણાદિંગ તદનન્તરમ્ |\nઅનુસ્વારઃ પરતરઃ | અર્ધેન્દુલસિતમ્ |\nતારેણ ઋદ્ધમ્ | એતત્તવ મનુસ્વરૂપમ્ |\nગકારઃ પૂર્વરૂપમ્ | અકારો મધ્યમરૂપમ્ |\nઅનુસ્વારશ્ચાન્ત્યરૂપમ્ | બિન્દુરુત્તરરૂપમ્ |\nનાદઃ સંધાનમ્ | સંહિતા સંધિઃ |\nસૈષા ગણેશવિદ્યા | ગણક ઋષિઃ |\nનિચૃદ્ગાયત્રીછન્દઃ | ગણપતિર્દેવતા |\nૐ ગં ગણપતયે નમઃ ||", "પહેલા 'ગ' કાર, પછી 'અ' કાર અને છેલ્લે ચંદ્રબિંદુ અનુસ્વારથી યુક્ત પ્રણવ 'ૐ' સાથે ઉચ્ચારાય છે. 'ૐ ગં ગણપતયે નમઃ' એ આપનો મૂળ મહામંત્ર છે. આ ગણેશ વિદ્યાના ઋષિ ગણક છે, છંદ નિચૃત્ ગાયત્રી છે અને દેવતા શ્રી મહાગણપતિ છે.", "મંત્ર ૯ (મૂળ મહામંત્ર)"),
            ScriptureVerse(11, "એકદંતાય વિદ્મહે વક્રતુંડાય ધીમહિ |\nતન્નો દંતિઃ પ્રચોદયાત્ ||", "અમે એકદંત પ્રભુને જાણીએ છીએ, વક્રતુંડ ગણેશનું ધ્યાન ધરીએ છીએ. તે દંતી ગણપતિ અમારી બુદ્ધિને સન્માર્ગે પ્રેરિત કરો.", "મંત્ર ૧૦ (ગણેશ ગાયત્રી)"),
            ScriptureVerse(12, "એકદંતં ચતુર્હસ્તં પાશમંકુશધારિણમ્ |\nરદં ચ વરદં હસ્તૈર્બિભ્રાણં મૂષકધ્વજમ્ |\nરક્તં લંબોદરં શૂર્પકર્ણકં રક્તવાસસમ્ |\nરક્તગંધાનુલિપ્તાંગં રક્તપુષ્પૈઃ સુપૂજિતમ્ |\nભક્તાનુકંપિનં દેવં જગત્કારણમચ્યુતમ્ |\nઆવિર્ભૂતં ચ સૃષ્ટ્યાદૌ પ્રકૃતેઃ પુરુષાત્પરમ્ |\nએવં ધ્યાયતિ યો નિત્યં સ યોગી યોગિનાં વરઃ ||", "એક દાંતવાળા, ચાર હાથવાળા, પાશ-અંકુશ-મોદક-વરદ મુદ્રા ધારણ કરનારા, લાલ વસ્ત્રધારી, લંબોદર, સૂપડા જેવા કાનવાળા, રાતા ચંદન અને લાલ જાસૂદથી પૂજિત, મૂષક વાહનવાળા શ્રી ગણેશનું જે નિત્ય ધ્યાન ધરે છે તે સર્વ યોગીઓમાં શ્રેષ્ઠ બને છે.", "મંત્ર ૧૧ (ધ્યાન સ્વરૂપ)"),
            ScriptureVerse(13, "નમો વ્રાતપતયે | નમો ગણપતયે |\nનમઃ પ્રમથપતયે | નમસ્તેઽસ્તુ લંબોદરાયૈકદન્તાય |\nવિઘ્નનાશિને શિવસુતાય શ્રીવરદમૂર્તયે નમઃ ||\nએતદથર્વશીર્ષં યોઽધીતે સ બ્રહ્મભૂયાય કલ્પતે |\nસ સર્વવિઘ્નૈર્ન બાધ્યતે | સ સર્વત્ર સુખમેધતે ||", "દેવોના નાથ, ગણોના અધિપતિ, શિવજીના ગણોના પ્રમુખ, લંબોદર, એકદંત, વિઘ્નહર્તા, શિવપુત્ર વરદમૂર્તિ ગણેશને વારંવાર નમસ્કાર! જે આ અથર્વશીર્ષનો પાઠ કરે છે તે બ્રહ્મપદ પ્રાપ્ત કરે છે, તેના સમસ્ત વિઘ્નો નાશ પામે છે અને તે સર્વત્ર સુખી બને છે.", "મંત્ર ૧૨-૧૩ (અષ્ટાંગ પ્રણામ અને ફલશ્રુતિ)")
        )
    )

    val durgaChalisa = DevotionalScripture(
        id = "durga_chalisa",
        titleGujarati = "શ્રી દુર્ગા ચાલીસા",
        deityName = "માતા દુર્ગા",
        category = ContentCategory.CHALISA,
        introductionGujarati = "આદ્યશક્તિ જગતજનની માં દુર્ગાની પરમ પાવન ચાલીસા, સંપૂર્ણ ૪૦ ચોપાઈ અને દોહા અર્થ સહિત.",
        verses = listOf(
            ScriptureVerse(1, "નમો નમો દુર્ગે સુખ કરની |\nનમો નમો અંબે દુઃખ હરની ||", "હે સુખ આપનારી માં દુર્ગા! આપને વારંવાર નમસ્કાર છે. હે સર્વ દુઃખો હરનારી જગદંબા અંબે માતા! આપને વારંવાર પ્રણામ છે.", "દોહા / ચોપાઈ ૧"),
            ScriptureVerse(2, "નિરૂપકાર દિવ્ય જ્યોતિ તુમ્હારી |\nતિહું લોક અજિયાલી ભારી ||", "આપનું કોઈ સાંસારિક રૂપ નથી છતાં આપની દિવ્ય અખંડ જ્યોતિથી ત્રણેય ભુવનોમાં અલૌકિક પ્રકાશ ફેલાઈ રહ્યો છે.", "ચોપાઈ ૨"),
            ScriptureVerse(3, "શશિ લલાટ મુખ મહાબિશાલા |\nનેત્ર લાલ ભૃકુટી બિકરાલા ||", "આપના મસ્તક પર ચંદ્રમા શોભે છે, મુખારવિંદ વિશાળ અને તેજોમય છે, રાતાં નેત્રો અને વિકરાળ ભૃકુટીથી દુષ્ટો થરથરે છે.", "ચોપાઈ ૩"),
            ScriptureVerse(4, "રૂપ માતુ કો અધિક સુહાવૈ |\nદંશ કિયે સબ સુખ ઉપજાવૈ ||", "માતાજીનું આ મોહક રૂપ અત્યંત દર્શનીય છે; જેના દર્શન માત્રથી હૃદયમાં અલૌકિક શાંતિ અને સુખની પ્રાપ્તિ થાય છે.", "ચોપાઈ ૪"),
            ScriptureVerse(5, "જય અંબે ગૌરી મૈયા જય શ્યામા ગૌરી |\nતુમકો નિશદિન ધ્યાવત હરિ બ્રહ્મા શિવરી ||", "હે અંબા માતા! હે ગૌરી મૈયા! આપની સદા જય હો. આપનું ભગવાન વિષ્ણુ, બ્રહ્માજી અને ભોળાનાથ શિવ નિશદિન ધ્યાન ધરે છે.", "ચોપાઈ ૫"),
            ScriptureVerse(6, "સિંહ વાહિની ત્રિશૂલધારિણી |\nમહિષાસુર મર્દિની દુષ્ટ સંહારિણી ||", "સિંહ પર સવારી કરનારી અને ત્રિશૂલ ધારણ કરનારી હે માં! આપે મહિષાસુર રાક્ષસનો વધ કરી દેવોને મુક્ત કર્યા.", "ચોપાઈ ૬"),
            ScriptureVerse(7, "ચંડ મુંડ સંહારક માતા |\nશુમ્ભ નિશુમ્ભ વિદારક દાતા ||", "આપે ચંડ અને મુંડ નામના ભયંકર દૈત્યોનો સંહાર કર્યો અને શુમ્ભ-નિશુમ્ભ જેવા અસુરોને પછાડી પૃથ્વીનો ભાર હળવો કર્યો.", "ચોપાઈ ૭"),
            ScriptureVerse(8, "રક્તબીજ જબ યુદ્ધ મચાયો |\nખપ્પર ભરી રક્ત સબ પિવાયો ||", "જ્યારે રક્તબીજ રાક્ષસે ઉપદ્રવ કર્યો ત્યારે આપે કાલી રૂપ ધરી તેના રક્તનું પાન કરી તેનો અંત આણ્યો.", "ચોપાઈ ૮"),
            ScriptureVerse(9, "ભક્ત જનોં કે કાજ સવારે |\nસંકટ પલ મેં સબ નિવારે ||", "આપ આપના શરણાગત ભક્તોના સઘળા કાર્યો સિદ્ધ કરો છો અને એક જ પલમાં સર્વ સંકટોનું નિવારણ કરો છો.", "ચોપાઈ ૯"),
            ScriptureVerse(10, "શ્રી દુર્ગા ચાલીસા જો ગાવૈ |\nસબ સુખ ભોગ પરમ પદ પાવૈ ||", "જે ભક્ત શ્રદ્ધાપૂર્વક આ દુર્ગા ચાલીસાનો પાઠ કરે છે, તે આ લોકમાં સર્વ સુખો ભોગવીને અંતે પરમ મોક્ષ પદ પામે છે.", "ચોપાઈ ૧૦ (સમાપન)")
        )
    )

